import json
import sys
import os
from collections import defaultdict

def load_config(config_path):
    with open(config_path, 'r') as f:
        return json.load(f)

def load_state():
    if os.path.exists('state.bin'):
        with open('state.bin', 'rb') as f:
            return json.load(f)
    return {}

def save_state(state):
    with open('state.bin', 'wb') as f:
        json.dump(state, f)

def process_input(config, state):
    output = []
    for line in sys.stdin:
        try:
            data = json.loads(line.strip())
            user = data['user']
            tokens = data['tokens']
            timestamp = data['timestamp']

            # Get user config or default to capacity=0, refill_per_second=0
            user_config = config.get(user, {'capacity': 0, 'refill_per_second': 0})
            capacity = user_config['capacity']
            refill_rate = user_config['refill_per_second']

            # Load or initialize user state
            if user not in state:
                state[user] = {
                    'tokens': capacity,
                    'last_update': timestamp
                }
            else:
                last_update = state[user]['last_update']
                if timestamp > last_update:
                    refill = (timestamp - last_update) * refill_rate
                    new_tokens = min(capacity, state[user]['tokens'] + refill)
                    state[user]['tokens'] = new_tokens
                    state[user]['last_update'] = timestamp

            # Check if tokens are available
            if state[user]['tokens'] >= tokens:
                state[user]['tokens'] -= tokens
                output.append({
                    'user': user,
                    'granted': True,
                    'remaining': state[user]['tokens']
                })
            else:
                output.append({
                    'user': user,
                    'granted': False,
                    'remaining': state[user]['tokens']
                })
        except json.JSONDecodeError:
            continue
    return output

def main():
    if len(sys.argv) != 2:
        print("Usage: python quota_throttle.py <config_file>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    config = load_config(config_path)
    state = load_state()

    output = process_input(config, state)
    for line in output:
        print(json.dumps(line))

    save_state(state)

if __name__ == "__main__":
    main()

