import json
import sys
import os
import pickle

class TokenBucket:
    def __init__(self, config):
        self.config = config
        self.capacity = config.get('capacity', 0)
        self.refill_per_second = config.get('refill_per_second', 0.0)
        self.tokens = 0.0
        self.last_update = 0.0

    def update(self, timestamp):
        if timestamp > self.last_update:
            self.tokens = min(self.capacity, self.tokens + (timestamp - self.last_update) * self.refill_per_second)
            self.last_update = timestamp

def load_state():
    if os.path.exists('state.bin'):
        with open('state.bin', 'rb') as f:
            return pickle.load(f)
    return {}

def save_state(state):
    with open('state.bin', 'wb') as f:
        pickle.dump(state, f)

def process_input(config, input_records):
    state = load_state()
    output = []

    for record in input_records:
        user = record['user']
        tokens_requested = record['tokens']
        timestamp = record['timestamp']

        # Initialize bucket if not exists
        if user not in state:
            config_entry = config.get(user)
            if config_entry:
                state[user] = TokenBucket(config_entry)
            else:
                state[user] = TokenBucket({'capacity': 0, 'refill_per_second': 0.0})

        bucket = state[user]
        bucket.update(timestamp)

        if bucket.tokens >= tokens_requested:
            bucket.tokens -= tokens_requested
            output.append({
                'user': user,
                'granted': True,
                'remaining': bucket.tokens
            })
        else:
            output.append({
                'user': user,
                'granted': False,
                'remaining': bucket.tokens
            })

    return output

def main():
    if len(sys.argv) != 2:
        print("Usage: python quota_throttle.py <config_file>", file=sys.stderr)
        sys.exit(1)

    config_file = sys.argv[1]
    with open(config_file, 'r') as f:
        config = json.load(f)

    input_records = []
    for line in sys.stdin:
        input_records.append(json.loads(line))

    output = process_input(config, input_records)

    for record in output:
        print(json.dumps(record))

    save_state(state)

if __name__ == "__main__":
    main()
